import java.util.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
final class PlayerDamagePatch implements Opcodes{
 static final String P="local/lito381/server/",C=P+"ClientSession",H=P+"CombatPlayerDamage";
 record Receiver(int slot,boolean entry){InsnList emit(){var i=new InsnList();i.add(new VarInsnNode(ALOAD,slot));if(entry){i.add(new MethodInsnNode(INVOKEINTERFACE,"java/util/Map$Entry","getKey","()Ljava/lang/Object;",true));i.add(new TypeInsnNode(CHECKCAST,C));}return i;}}
 static AbstractInsnNode one(SourceValue v){if(v.insns.size()!=1)throw new IllegalStateException("ambiguous signed PC commit operand");return v.insns.iterator().next();}
 static int load(SourceValue v,int code){var n=one(v);if(!(n instanceof VarInsnNode x)||x.getOpcode()!=code)throw new IllegalStateException("bad signed PC commit local");return x.var;}
 static Receiver receiver(SourceValue v,Frame<SourceValue>[] f,Map<AbstractInsnNode,Integer> ix){var n=one(v);if(n instanceof VarInsnNode x&&x.getOpcode()==ALOAD)return new Receiver(x.var,false);if(!(n instanceof TypeInsnNode cast)||cast.getOpcode()!=CHECKCAST||!cast.desc.equals(C))throw new IllegalStateException("unknown PC commit receiver");var at=f[ix.get(n)];var get=one(at.getStack(at.getStackSize()-1));if(!(get instanceof MethodInsnNode m)||!m.owner.equals("java/util/Map$Entry")||!m.name.equals("getKey"))throw new IllegalStateException("unknown PC map receiver");var frame=f[ix.get(get)];return new Receiver(load(frame.getStack(frame.getStackSize()-1),ALOAD),true);}
 static String damage(SourceValue v,Frame<SourceValue>[] f,Map<AbstractInsnNode,Integer> ix){var n=one(v);if(n instanceof VarInsnNode x&&x.getOpcode()==ILOAD)return "local:"+x.var;if(!(n instanceof MethodInsnNode m)||!m.owner.equals("java/lang/Integer")||!m.name.equals("intValue"))throw new IllegalStateException("unknown PC signed damage producer");var frame=f[ix.get(n)];var cast=one(frame.getStack(frame.getStackSize()-1));if(!(cast instanceof TypeInsnNode))throw new IllegalStateException("missing PC Integer map cast");var before=f[ix.get(cast)];var value=one(before.getStack(before.getStackSize()-1));if(!(value instanceof MethodInsnNode m2)||!m2.owner.equals("java/util/Map$Entry")||!m2.name.equals("getValue"))throw new IllegalStateException("missing PC entry damage");var actor=f[ix.get(value)];return "entry:"+load(actor.getStack(actor.getStackSize()-1),ALOAD);}
 static void apply(ClassNode c,Map<String,Integer> hooks)throws AnalyzerException{
  var paths=new TreeMap<String,Integer>();int gates=0,minds=0,dolls=0,wires=0;
  for(var m:c.methods){boolean scoped=MagicDamagePatch.MIRRORS.containsKey(m.name)||Set.of("useShockStunSpell","useClassicWorldShockStunSpell","useCounterDetectionSpell","useClassicWorldCounterDetectionSpell").contains(m.name);boolean doll=m.name.equals("applyNativeMagicDollAttackProcs");if(!scoped&&!doll)continue;m.maxStack+=64;var nodes=m.instructions.toArray();var frames=new Analyzer<>(new SourceInterpreter()).analyze(c.name,m);var ix=new IdentityHashMap<AbstractInsnNode,Integer>();for(int at=0;at<nodes.length;at++)ix.put(nodes[at],at);
   for(int at=0;at<nodes.length;at++)if(nodes[at] instanceof MethodInsnNode call){
    if(scoped&&call.owner.equals(C)&&Set.of("takePlayerDamage","takeClassicWorldPlayerDamage").contains(call.name)){
     var frame=frames[at];int pos=frame.getStackSize()-Type.getArgumentTypes(call.desc).length-1;var target=receiver(frame.getStack(pos),frames,ix);var key=damage(frame.getStack(pos+1),frames,ix);if(load(frame.getStack(pos+2),ALOAD)!=0)throw new IllegalStateException("signed PC commit caster drift");boolean world=call.name.equals("takeClassicWorldPlayerDamage");
     if(world&&!m.name.equals("useClassicWorldCounterDetectionSpell")){JumpInsnNode found=null;for(int j=at-1;j>=0;j--)if(nodes[j] instanceof JumpInsnNode jump&&jump.getOpcode()==IFLE&&ix.get(jump.label)>at&&frames[j]!=null){var f=frames[j];String value;try{value=damage(f.getStack(f.getStackSize()-1),frames,ix);}catch(IllegalStateException ignored){continue;}if(value.equals(key)){found=jump;break;}}if(found==null)throw new IllegalStateException("missing native positive WORLD commit guard="+m.name);var i=target.emit();i.add(new VarInsnNode(ALOAD,0));i.add(new MethodInsnNode(INVOKESTATIC,H,"worldGate","(IL"+C+";L"+C+";)I",false));m.instructions.insertBefore(found,i);gates++;}
     String name=world?"world":call.desc.equals("(IL"+C+";)V")?"battle":"battleTerminal";if(!world&&!Set.of("(IL"+C+";)V","(IL"+C+";ZZJ)V").contains(call.desc))throw new IllegalStateException("unknown PC HP overload");m.instructions.set(call,new MethodInsnNode(INVOKESTATIC,H,name,"(L"+C+";"+call.desc.substring(1),false));paths.merge(m.name,1,Integer::sum);
    }else if(scoped&&call.owner.equals(P+"BattleSpellCatalog$MindBreakSpell")&&call.name.equals("damageAfterMultiplier")){m.instructions.set(call,new MethodInsnNode(INVOKESTATIC,H,"mindMultiplier","(L"+call.owner+";I)I",false));minds++;}
    if(scoped&&call.owner.equals(P+"Protocol")&&call.name.equals("shockStunAttack")){var frame=frames[at];var scalar=one(frame.getStack(frame.getStackSize()-2));if(!(scalar instanceof VarInsnNode v)||v.getOpcode()!=ILOAD){if(scalar.getOpcode()==ICONST_0)continue;throw new IllegalStateException("unknown Shock display damage operand");}if(!Set.of("useShockStunSpell","useClassicWorldShockStunSpell").contains(m.name)||!call.desc.equals("(IJJII)[B"))throw new IllegalStateException("source signed Shock wire shape");m.instructions.set(call,new MethodInsnNode(INVOKESTATIC,H,"shockWire",call.desc,false));wires++;}
    if(doll&&call.owner.equals(C)&&call.name.equals("nativeMagicDollTriggeredSkillDamage")){var next=DragonPatch.next(call);if(!(next instanceof VarInsnNode store)||store.getOpcode()!=ISTORE)throw new IllegalStateException("missing native doll damage local");JumpInsnNode found=null;for(int j=at+1;j<nodes.length;j++)if(nodes[j] instanceof JumpInsnNode jump&&jump.getOpcode()==IFLE&&frames[j]!=null){var f=frames[j];var value=one(f.getStack(f.getStackSize()-1));if(value instanceof VarInsnNode v&&v.getOpcode()==ILOAD&&v.var==store.var){found=jump;break;}}if(found==null)throw new IllegalStateException("missing native doll positive commit guard");var i=new InsnList();i.add(new VarInsnNode(ALOAD,4));i.add(new VarInsnNode(ALOAD,0));i.add(new MethodInsnNode(INVOKESTATIC,H,"dollGate","(IL"+C+";L"+C+";)I",false));m.instructions.insertBefore(found,i);dolls++;}
   }
  }
  System.out.println("source-signed-PC-commit-paths="+paths);CombatPatch.require(paths.size(),17,"signed native PC commit method count");if(paths.values().stream().anyMatch(v->v!=1))throw new IllegalStateException("duplicate native PC HP commits");CombatPatch.require(gates,8,"signed WORLD positive-only gates");CombatPatch.require(minds,4,"signed Mind Break mode multipliers");CombatPatch.require(dolls,1,"signed native doll PC gate");CombatPatch.require(wires,2,"signed Shock damage display adapters");hooks.put("source-signed-shock-wire",wires);hooks.put("source-signed-player-hp",17);hooks.put("source-signed-world-gates",gates);hooks.put("source-signed-mind-mode",minds);hooks.put("source-signed-doll-gate",dolls);
 }
}
